import java.util.*;
import java.io.*;

public class Solution {
    public static void main(String[] args) throws Exception {
        DataInputStream dis = new DataInputStream(System.in);
        int n = readInt(dis);
        int k = readInt(dis);
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = readInt(dis);
        }
        int evenCount = 0, oddCount = 0;
        ArrayList<Integer> diffList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (i != 0) {
                if (evenCount == oddCount) {
                    diffList.add(Math.abs(arr[i] - arr[i - 1]));
                }
            }
            if (arr[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
        }
        Collections.sort(diffList);
        int total = 0;
        for (int val : diffList) {
            if (val <= k) {
                total++;
                k -= val;
            } else {
                break;
            }
        }
        System.out.println(total);
    }

    static int readInt(DataInputStream dis) throws IOException {
        int result = 0;
        int c;
        while ((c = dis.read()) != -1 && !Character.isDigit(c));
        do {
            result = result * 10 + (c - '0');
        } while ((c = dis.read()) != -1 && Character.isDigit(c));
        return result;
    }
}
